# Generated by Claudian.
"""Local intent classifier — the fast path in front of the Groq LLM fallback.

The router previously sent every low-confidence utterance to Groq purely to
decide *which skill to run*: a 300-500ms network round trip before any work
began.  This model answers the same question in ~0.1ms.

CONFIDENCE GATING
-----------------
The model does not always answer.  Below `threshold` (chosen at training
time as the lowest softmax confidence that is essentially never wrong on
held-out data) it returns None and the router falls through to the LLM.
That keeps LLM-grade accuracy on genuinely ambiguous input while taking the
fast path on the ~94% of traffic that is unambiguous.

Loading is lazy and failure is non-fatal: if the model files are missing or
torch is unavailable, `available` stays False and the router behaves exactly
as it did before.
"""

from __future__ import annotations

import json
import pickle
import threading
from pathlib import Path
from typing import Optional

from utils.logger import get_logger

logger = get_logger(__name__)

MODEL_DIR = Path(__file__).parent.parent / "data" / "models"
MODEL_PATH = MODEL_DIR / "intent_model.pt"
VECTORIZER_PATH = MODEL_DIR / "intent_vectorizer.pkl"
LABELS_PATH = MODEL_DIR / "intent_labels.json"
METRICS_PATH = MODEL_DIR / "intent_metrics.json"

DEFAULT_THRESHOLD = 0.7


class LocalIntentClassifier:
    def __init__(self) -> None:
        self.available = False
        self.threshold = DEFAULT_THRESHOLD
        self._model = None
        self._char_vec = None
        self._word_vec = None
        self._labels: list[str] = []
        self._torch = None
        # Inference runs on the shared thread pool; guard the forward pass.
        self._lock = threading.Lock()
        self._load()

    # ── Loading ──────────────────────────────────────────────────────────

    def _load(self) -> None:
        if not (MODEL_PATH.exists() and VECTORIZER_PATH.exists() and LABELS_PATH.exists()):
            logger.info(
                "Local intent model not found — router will use the LLM fallback. "
                "Train it with: python3 training/train_intent_model.py --epochs 100"
            )
            return

        try:
            import torch
            import torch.nn as nn
        except ImportError:
            logger.warning("torch unavailable — local intent model disabled")
            return

        try:
            with open(VECTORIZER_PATH, "rb") as f:
                vecs = pickle.load(f)
            self._char_vec = vecs["char"]
            self._word_vec = vecs["word"]

            with open(LABELS_PATH) as f:
                self._labels = json.load(f)

            if METRICS_PATH.exists():
                with open(METRICS_PATH) as f:
                    metrics = json.load(f)
                gate = metrics.get("confidence_gate")
                if isinstance(gate, (int, float)) and 0 < gate < 1:
                    self.threshold = float(gate)

            ckpt = torch.load(MODEL_PATH, map_location="cpu", weights_only=False)

            # Mirrors IntentNet in training/train_intent_model.py.
            hidden = ckpt.get("hidden", 256)
            model = nn.Sequential(
                nn.Linear(ckpt["in_dim"], hidden),
                nn.ReLU(),
                nn.Dropout(0.3),
                nn.Linear(hidden, hidden // 2),
                nn.ReLU(),
                nn.Dropout(0.2),
                nn.Linear(hidden // 2, ckpt["n_classes"]),
            )
            # Training wrapped these in a `net` Sequential; strip the prefix.
            state = {k.replace("net.", "", 1): v for k, v in ckpt["state_dict"].items()}
            model.load_state_dict(state)
            model.eval()

            self._torch = torch
            self._model = model
            self.available = True
            logger.info(
                f"Local intent model loaded — {len(self._labels)} classes, "
                f"confidence gate {self.threshold}"
            )
        except Exception as e:
            logger.error(f"Failed to load local intent model: {e}")
            self.available = False

    # ── Inference ────────────────────────────────────────────────────────

    def predict(self, text: str) -> tuple[Optional[str], float]:
        """Return (skill_name, confidence). Confidence is 0.0 when unavailable."""
        if not self.available or not text.strip():
            return None, 0.0

        try:
            import numpy as np

            a = self._char_vec.transform([text]).toarray()
            b = self._word_vec.transform([text]).toarray()
            x = np.hstack([a, b]).astype("float32")

            with self._lock:
                tensor = self._torch.from_numpy(x)
                with self._torch.no_grad():
                    probs = self._torch.softmax(self._model(tensor), dim=1)[0]
                conf, idx = probs.max(dim=0)

            return self._labels[int(idx)], float(conf)
        except Exception as e:
            logger.debug(f"Local intent prediction failed: {e}")
            return None, 0.0

    def predict_gated(self, text: str) -> tuple[Optional[str], float]:
        """Predict, but return None when below the confidence gate.

        This is what the router calls: a None means "I'm not sure, ask the LLM".
        """
        skill, conf = self.predict(text)
        if skill is None or conf < self.threshold:
            return None, conf
        return skill, conf


_singleton: Optional[LocalIntentClassifier] = None
_singleton_lock = threading.Lock()


def get_local_classifier() -> LocalIntentClassifier:
    global _singleton
    if _singleton is None:
        with _singleton_lock:
            if _singleton is None:
                _singleton = LocalIntentClassifier()
    return _singleton
